          f"cov={r['coverage_asset_days']:.3f} maxcorr={r['max_abs_library_correlation']} "
          f"-> {'PASS' if g['pass'] else 'FAIL'}", flush=True)

with open("scripts/miner_1_cycle21_results.json", "w") as f:
    json.dump(results, f, indent=1, default=str)
